def _enumerate_paths(nN, E, S, B):
    camps = set(B)
    paths = []
    def extend(path):
        i = path[-1]
        if i in camps:
            paths.append(list(path))
            return
        for j in range(nN):
            if E[i][j] and j not in path:
                extend(path + [j])
    for s in S:
        extend([s])
    return paths
paths = _enumerate_paths(nN, E, S, B)

def _enumerate_cycles(nN, E):
    adj = [[j for j in range(nN) if E[i][j] == 1] for i in range(nN)]
    cycles = []
    for start in range(nN):
        path = [start]
        on_path = {start}
        def dfs(v):
            for w in adj[v]:
                if w == start:
                    edges = [(path[idx], path[idx + 1]) for idx in range(len(path) - 1)]
                    edges.append((v, start))
                    cycles.append(edges)
                elif w > start and w not in on_path:
                    path.append(w)
                    on_path.add(w)
                    dfs(w)
                    path.pop()
                    on_path.discard(w)
        dfs(start)
    return cycles
cycles = _enumerate_cycles(nN, E)
